content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-color: #1f2937;
  --text-muted: #6b7280;
  --border-color: #e5e7eb;
  --accent-color: #10b981;
  --danger-color: #ef4444;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.app-container {
  width: 100%;
  max-width: 600px;
  margin: 0 auto;
  padding: 2rem;
  background-color: var(--card-bg);
  border-radius: 1rem;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);
  text-align: center;
}

.title {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
  color: var(--text-color);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 0.5rem;
  border: none;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.game-box {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.timer {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--danger-color);
  background-color: #fee2e2;
  padding: 0.5rem 1rem;
  border-radius: 2rem;
  display: inline-block;
  margin: 0 auto;
}

.score {
  font-size: 1.1rem;
  color: var(--text-muted);
}

.target-word {
  font-size: 2.5rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--text-color);
  margin-top: 1rem;
}

.romaji {
  font-size: 1.5rem;
  color: var(--text-muted);
  font-family: monospace;
  letter-spacing: 0.1em;
  margin-bottom: 1rem;
}

.input-box {
  width: 100%;
  padding: 1rem;
  font-size: 1.25rem;
  text-align: center;
  border: 2px solid var(--border-color);
  border-radius: 0.5rem;
  outline: none;
  transition: border-color 0.2s;
  font-family: monospace;
}

.input-box:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.15);
}

.result-box {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  align-items: center;
}

.stat-item {
  font-size: 1.2rem;
  background-color: #f9fafb;
  padding: 0.75rem 1.5rem;
  border-radius: 0.5rem;
  border: 1px solid var(--border-color);
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

export type GameState = 'start' | 'playing' | 'result';

export interface WordItem {
  id: number;
  kanji: string;
  kana: string;
  romaji: string;
}

export interface GameStats {
  typedCount: number;
  correctCount: number;
  missCount: number;
}

import { useState } from 'react';
import './index.css';
import { GameState, GameStats } from './types';
import GameScreen from './components/GameScreen';
import ResultScreen from './components/ResultScreen';

export default function App() {
  const [gameState, setGameState] = useState<GameState>('start');
  const [stats, setStats] = useState<GameStats>({
    typedCount: 0,
    correctCount: 0,
    missCount: 0,
  });

  const handleStartGame = () => {
    setStats({ typedCount: 0, correctCount: 0, missCount: 0 });
    setGameState('playing');
  };

  const handleFinishGame = (finalStats: GameStats) => {
    setStats(finalStats);
    setGameState('result');
  };

  return (
    <div className="app-container">
      {gameState === 'start' && (
        <div>
          <h1 className="title">ローマ字タイピングゲーム</h1>
          <p style={{ marginBottom: '1.5rem', color: 'var(--text-muted)' }}>
            60秒間で何文字打てるかに挑戦しよう！
          </p>
          <button className="btn btn-primary" onClick={handleStartGame}>
            ゲームスタート
          </button>
        </div>
      )}

      {gameState === 'playing' && (
        <GameScreen onFinish={handleFinishGame} />
      )}

      {gameState === 'result' && (
        <ResultScreen stats={stats} onRestart={handleStartGame} />
      )}
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import '../index.css';
import { WordItem, GameStats } from '../types';

const WORD_LIST: WordItem[] = [
  { id: 1, kanji: '日本語', kana: 'にほんご', romaji: 'nihongo' },
  { id: 2, kanji: '寿司', kana: 'すし', romaji: 'sushi' },
  { id: 3, kanji: '桜', kana: 'さくら', romaji: 'sakura' },
  { id: 4, kanji: '猫', kana: 'ねこ', romaji: 'neko' },
  { id: 5, kanji: '犬', kana: 'いぬ', romaji: 'inu' },
  { id: 6, kanji: '富士山', kana: 'ふじさん', romaji: 'fujisan' },
  { id: 7, kanji: '未来', kana: 'みらい', romaji: 'mirai' },
  { id: 8, kanji: '勉強', kana: 'べんきょう', romaji: 'benkyou' },
  { id: 9, kanji: '学校', kana: 'がっこう', romaji: 'gakkou' },
  { id: 10, kanji: 'パソコン', kana: 'ぱそこん', romaji: 'pasokon' },
  { id: 11, kanji: '情報', kana: 'じょうほう', romaji: 'jouhou' },
  { id: 12, kanji: '開発', kana: 'かいはつ', romaji: 'kaihatsu' },
  { id: 13, kanji: '挑戦', kana: 'ちょうせん', romaji: 'chousen' },
  { id: 14, kanji: '画面', kana: 'がめん', romaji: 'gamen' },
  { id: 15, kanji: '時間', kana: 'じかん', romaji: 'jikan' },
];

interface GameScreenProps {
  onFinish: (stats: GameStats) => void;
}

export default function GameScreen({ onFinish }: GameScreenProps) {
  const [timeLeft, setTimeLeft] = useState<number>(60);
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [inputVal, setInputVal] = useState<string>('');
  const [correctCount, setCorrectCount] = useState<number>(0);
  const [missCount, setMissCount] = useState<number>(0);
  const [typedCount, setTypedCount] = useState<number>(0);

  const inputRef = useRef<HTMLInputElement>(null);
  const currentWord: WordItem = WORD_LIST[currentIndex % WORD_LIST.length];

  useEffect(() => {
    inputRef.current?.focus();
  }, [currentIndex]);

  useEffect(() => {
    if (timeLeft <= 0) {
      onFinish({
        typedCount,
        correctCount,
        missCount,
      });
      return;
    }

    const timer = setInterval(() => {
      setTimeLeft((prev) => prev - 1);
    }, 1000);

    return () => clearInterval(timer);
  }, [timeLeft, typedCount, correctCount, missCount, onFinish]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setInputVal(value);
    setTypedCount((prev) => prev + 1);

    // 完全一致判定
    if (value === currentWord.romaji) {
      setCorrectCount((prev) => prev + currentWord.romaji.length);
      setCurrentIndex((prev) => prev + 1);
      setInputVal('');
    } else {
      // プレフィックス一致しているか確認、していなければミス判定とする簡易ロジック
      if (!currentWord.romaji.startsWith(value)) {
        setMissCount((prev) => prev + 1);
      }
    }
  };

  return (
    <div className="game-box">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div className="timer">残り時間: {timeLeft}秒</div>
        <div className="score">正解文字数: {correctCount}</div>
      </div>

      <div>
        <div className="target-word">{currentWord.kanji}</div>
        <div className="romaji">{currentWord.romaji}</div>
      </div>

      <input
        ref={inputRef}
        type="text"
        className="input-box"
        value={inputVal}
        onChange={handleInputChange}
        placeholder="ここに入力..."
        autoComplete="off"
        autoCapitalize="none"
        spellCheck="false"
      />
    </div>
  );
}

import '../index.css';
import { GameStats } from '../types';

interface ResultScreenProps {
  stats: GameStats;
  onRestart: () => void;
}

export default function ResultScreen({ stats, onRestart }: ResultScreenProps) {
  return (
    <div className="result-box">
      <h1 className="title">結果発表</h1>

      <div className="stat-item">
        <span>正しく打てた文字数</span>
        <strong>{stats.correctCount} 文字</strong>
      </div>

      <div className="stat-item">
        <span>総入力数</span>
        <strong>{stats.typedCount} 回</strong>
      </div>

      <div className="stat-item">
        <span>ミス回数</span>
        <strong style={{ color: 'var(--danger-color)' }}>{stats.missCount} 回</strong>
      </div>

      <button className="btn btn-primary" onClick={onRestart} style={{ width: '100%', marginTop: '1rem' }}>
        もう一度挑戦する
      </button>
    </div>
  );
}
